// MVVM-style architecture with hooks in React Native
import { useState, useEffect, useCallback } from 'react';

function useUserViewModel(userId) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  const fetchUser = useCallback(async () => {
    setLoading(true);
    try {
      const response = await api.getUser(userId);
      setUser(response.data);
    } finally {
      setLoading(false);
    }
  }, [userId]);

  useEffect(() => { fetchUser(); }, [fetchUser]);

  return { user, loading, refresh: fetchUser };
}

function UserProfileScreen({ route }) {
  const { user, loading } = useUserViewModel(route.params.userId);
  if (loading) return <Spinner />;
  return <ProfileView user={user} />;
}

