import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*

// Data class with sealed class for network results
data class User(val id: Long, val name: String, val email: String)

sealed class NetworkResult<out T> {
    data class Success<T>(val data: T) : NetworkResult<T>()
    data class Error(val message: String, val code: Int) : NetworkResult<Nothing>()
    data object Loading : NetworkResult<Nothing>()
}

// Extension function
fun String.isValidEmail(): Boolean {
    return this.contains("@") && this.contains(".")
}

// Null safety examples
fun getUserDisplayName(user: User?): String {
    val name = user?.name ?: "Anonymous"
    val email = user?.email ?: return "No email"
    return "$name <$email>"
}

// Coroutine example with error handling
class UserRepository(private val api: UserApi) {
    suspend fun fetchUser(id: Long): NetworkResult<User> = withContext(Dispatchers.IO) {
        try {
            val user = api.getUser(id) // suspend function call
            NetworkResult.Success(user)
        } catch (e: IOException) {
            NetworkResult.Error("Network error: ${e.message}", 503)
        } catch (e: Exception) {
            NetworkResult.Error(e.message ?: "Unknown error", 500)
        }
    }

    suspend fun fetchMultipleUsers(ids: List<Long>): List<User> = coroutineScope {
        ids.map { id -> async { api.getUser(id) } }.awaitAll()
    }
}

// ViewModel with StateFlow
class UserViewModel(private val repo: UserRepository) : ViewModel() {
    private val _user = MutableStateFlow<NetworkResult<User>>(NetworkResult.Loading)
    val user: StateFlow<NetworkResult<User>> = _user.asStateFlow()

    fun loadUser(id: Long) {
        viewModelScope.launch {
            _user.value = repo.fetchUser(id)
        }
    }
}

