// WorkManager setup
class SyncWorker(
    context: Context,
    params: WorkerParameters
) : CoroutineWorker(context, params) {

    override suspend fun doWork(): Result {
        return withContext(Dispatchers.IO) {
            try {
                val api = RetrofitClient.instance
                val localDb = AppDatabase.getInstance(applicationContext)

                // Sync local changes to remote
                val pendingChanges = localDb.syncDao().getPendingChanges()
                for (change in pendingChanges) {
                    api.syncData(change.toDto())
                    localDb.syncDao().markSynced(change.id)
                }

                // Fetch remote updates
                val remoteData = api.fetchUpdates(since = lastSyncTimestamp())
                localDb.remoteDao().insertAll(remoteData)

                Result.success()
            } catch (e: IOException) {
                if (runAttemptCount < 3) Result.retry() else Result.failure()
            }
        }
    }

    override suspend fun getForegroundInfo(): ForegroundInfo {
        return ForegroundInfo(
            NOTIFICATION_ID,
            createNotification("Syncing data...")
        )
    }
}

// Schedule the work
class SyncScheduler(private val context: Context) {

    fun schedulePeriodicSync() {
        val constraints = Constraints.Builder()
            .setRequiredNetworkType(NetworkType.CONNECTED)
            .setRequiresCharging(false)
            .setRequiresBatteryNotLow(true)
            .build()

        val syncRequest = PeriodicWorkRequestBuilder<SyncWorker>(
            repeatInterval = 15,
            repeatIntervalTimeUnit = TimeUnit.MINUTES
        )
            .setConstraints(constraints)
            .setBackoffCriteria(
                BackoffPolicy.EXPONENTIAL,
                WorkRequest.MIN_BACKOFF_MILLIS,
                TimeUnit.MILLISECONDS
            )
            .addTag("data_sync")
            .build()

        WorkManager.getInstance(context)
            .enqueueUniquePeriodicWork(
                "periodic_sync",
                ExistingPeriodicWorkPolicy.KEEP,
                syncRequest
            )
    }
}

// Notification channel setup
fun createNotificationChannel(context: Context) {
    val channel = NotificationChannel(
        SYNC_CHANNEL_ID,
        "Data Sync",
        NotificationManager.IMPORTANCE_LOW
    ).apply {
        description = "Shows sync progress and status"
        setShowBadge(false)
    }
    val manager = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
    manager.createNotificationChannel(channel)
