// Retrofit instance with OkHttp client
object RetrofitClient {

    private const val BASE_URL = "https://api.example.com/v1/"
    private const val CACHE_SIZE = 10L * 1024 * 1024 // 10 MB

    private val cache = Cache(
        File(System.getProperty("java.io.tmpdir"), "http-cache"),
        CACHE_SIZE
    )

    private val loggingInterceptor = HttpLoggingInterceptor().apply {
        level = HttpLoggingInterceptor.Level.BODY
    }

    private val authInterceptor = Interceptor { chain ->
        val request = chain.request().newBuilder()
            .addHeader("Authorization", "Bearer ${SessionManager.token}")
            .addHeader("Accept", "application/json")
            .build()
        chain.proceed(request)
    }

    private val retryInterceptor = Interceptor { chain ->
        var response = chain.proceed(chain.request())
        var attempt = 0
        while (!response.isSuccessful && attempt < 3) {
            if (response.code in listOf(503, 429)) {
                Thread.sleep(1000L * (attempt + 1))
                response.close()
                response = chain.proceed(chain.request())
                attempt++
            } else {
                break
            }
        }
        response
    }

    private val okHttpClient = OkHttpClient.Builder()
        .cache(cache)
        .connectTimeout(30, TimeUnit.SECONDS)
        .readTimeout(30, TimeUnit.SECONDS)
        .writeTimeout(30, TimeUnit.SECONDS)
        .addInterceptor(authInterceptor)
        .addInterceptor(loggingInterceptor)
        .addInterceptor(retryInterceptor)
        .build()

    val instance: ApiService = Retrofit.Builder()
        .baseUrl(BASE_URL)
        .client(okHttpClient)
        .addConverterFactory(Json.asConverterFactory("application/json".toMediaType()))
        .build()
        .create(ApiService::class.java)
}

