    companion object {
        private val KEY_THEME = booleanPreferencesKey("dark_theme")
        private val KEY_USER_ID = stringPreferencesKey("active_user_id")
    }

    val isDarkTheme: Flow<Boolean> = context.dataStore.data
        .map { it[KEY_THEME] ?: false }

    val activeUserId: Flow<String?> = context.dataStore.data
        .map { it[KEY_USER_ID] }

    suspend fun setDarkTheme(enabled: Boolean) {
        context.dataStore.edit { prefs ->
            prefs[KEY_THEME] = enabled
        }
    }

    suspend fun setActiveUserId(id: String?) {
        context.dataStore.edit { prefs ->
            if (id != null) prefs[KEY_USER_ID] = id
            else prefs.remove(KEY_USER_ID)
        }
    }
}

