import Foundation

// Codable model for JSON persistence
struct TaskItem: Codable, Identifiable {
    let id: UUID
    var title: String
    var isCompleted: Bool
    let createdAt: Date
}

// JSON file-based persistence service
final class TaskPersistenceService {
    private let fileURL: URL

    init() {
        let documents = FileManager.default.urls(
            for: .documentDirectory,
            in: .userDomainMask
        ).first!
        fileURL = documents.appendingPathComponent("tasks.json")
    }

    func save(_ tasks: [TaskItem]) throws {
        let data = try JSONEncoder().encode(tasks)
        try data.write(to: fileURL, options: .atomic)
    }

    func load() throws -> [TaskItem] {
        guard FileManager.default.fileExists(atPath: fileURL.path) else {
            return []
        }
        let data = try Data(contentsOf: fileURL)
        return try JSONDecoder().decode([TaskItem].self, from: data)
    }
}

