import Foundation

// Actor for safe concurrent state
actor TaskManager {
    private var tasks: [TaskItem] = []

    func addTask(_ task: TaskItem) {
        tasks.append(task)
    }

    func completeTask(id: UUID) {
        guard let index = tasks.firstIndex(where: { $0.id == id })
        else { return }
        var updated = tasks[index]
        updated.isCompleted = true
        tasks[index] = updated
    }

    func pendingTasks() async -> [TaskItem] {
        return tasks.filter { !$0.isCompleted }
    }
}

// Async/await with TaskGroup for parallel work
func loadAllData() async throws -> [TaskItem] {
    return try await withThrowingTaskGroup(of: [TaskItem].self) { group in
        let remoteService = TaskAPIService()
        let localService = TaskPersistenceService()

        group.addTask {
            return try await remoteService.fetchTasks()
        }
        group.addTask {
            return try localService.load()
        }

        var allTasks: [TaskItem] = []
        for try await result in group {
            allTasks.append(contentsOf: result)
        }
        return allTasks
    }
}

// MainActor usage for UI updates
@MainActor
final class TaskListViewModel: ObservableObject {
    @Published var tasks: [TaskItem] = []
    let manager = TaskManager()

    func refresh() async throws {
        let loaded = try await loadAllData()
        for task in loaded {
            await manager.addTask(task)
        }
        self.tasks = await manager.pendingTasks()
    }
}

