// Riverpod (StateNotifier)
import 'package:flutter_riverpod/flutter_riverpod.dart';

final cartProvider = StateNotifierProvider<CartNotifier, List<String>>(
  (ref) => CartNotifier(),
);

class CartNotifier extends StateNotifier<List<String>> {
  CartNotifier() : super([]);

  void add(String item) => state = [...state, item];
  void remove(String item) =>
      state = state.where((i) => i != item).toList();
}

// Bloc
import 'package:flutter_bloc/flutter_bloc.dart';

sealed class CartEvent {}
final class AddItem extends CartEvent { final String item; AddItem(this.item); }
final class RemoveItem extends CartEvent { final String item; RemoveItem(this.item); }

class CartBloc extends Bloc<CartEvent, List<String>> {
  CartBloc() : super([]) {
    on<AddItem>((event, emit) => emit([...state, event.item]));
    on<RemoveItem>((event, emit) =>
        emit(state.where((i) => i != event.item).toList()));
  }
}

