// Redux Toolkit slice
import { createSlice, configureStore } from '@reduxjs/toolkit';

const cartSlice = createSlice({
  name: 'cart',
  initialState: { items: [] as string[], total: 0 },
  reducers: {
    addItem: (state, action) => {
      state.items.push(action.payload);
      state.total = state.items.length * 9.99;
    },
    removeItem: (state, action) => {
      state.items = state.items.filter((i) => i !== action.payload);
      state.total = state.items.length * 9.99;
    },
  },
});

export const { addItem, removeItem } = cartSlice.actions;
export const store = configureStore({ reducer: { cart: cartSlice.reducer } });

// Zustand
import { create } from 'zustand';

interface CartStore {
  items: string[];
  total: number;
  addItem: (item: string) => void;
  removeItem: (item: string) => void;
}

export const useCartStore = create<CartStore>((set) => ({
  items: [],
  total: 0,
  addItem: (item) =>
    set((state) => ({
      items: [...state.items, item],
      total: (state.items.length + 1) * 9.99,
    })),
  removeItem: (item) =>
    set((state) => {
      const items = state.items.filter((i) => i !== item);
      return { items, total: items.length * 9.99 };
    }),
}));

