import * as tf from '@tensorflow/tfjs';
import '@tensorflow/tfjs-react-native';
import { bundleResourceIO, decodeJpeg } from '@tensorflow/tfjs-react-native';

async function runInference(imageUri) {
  // Load the model from app bundle
  const modelJson = require('./model.json');
  const modelWeights = require('./weights.bin');
  const model = await tf.loadGraphModel(
    bundleResourceIO(modelJson, modelWeights)
  );

  // Preprocess image
  const imageAsset = await fetch(imageUri);
  const imageData = await imageAsset.arrayBuffer();
  const imageTensor = decodeJpeg(new Uint8Array(imageData), 3);
  const resized = tf.image.resizeBilinear(imageTensor, [224, 224]);
  const normalized = resized.div(255.0).expandDims(0);

  // Run inference
  const prediction = model.predict(normalized);
  const scores = await prediction.data();

  // Clean up tensors
  tf.dispose([imageTensor, resized, normalized, prediction]);

  return scores;
}

