        Crashlytics.Log(eventName);
        if (data != null) {
            foreach (var kv in data) {
                Crashlytics.SetCustomKey(kv.Key, 
                    kv.Value?.ToString() ?? "null");
            }
        }
    }

    // Set user identifier (anonymized)
    public static void SetUserId(string userId) {
        Crashlytics.SetUserId(userId);
    }

    // Non-fatal exception logging
    public static void LogNonFatal(Exception e, 
        string context = null) {
        if (context != null) Crashlytics.Log(context);
        Crashlytics.LogException(e);
    }

    // Track scene changes
    void OnSceneLoaded(Scene scene, LoadSceneMode mode) {
        Crashlytics.Log($"Scene loaded: {scene.name}");
        Crashlytics.SetCustomKey("current_scene", scene.name);
