class VirtualJoystick {
    constructor(centerX, centerY, radius) {
        this.center = { x: centerX, y: centerY };
        this.radius = radius;
        this.active = false;
        this.value = { x: 0, y: 0 };
    }

    handleTouch(id, phase, pos) {
        if (phase === 'began' && this.hitTest(pos)) {
            this.active = true;
            this.touchId = id;
        }
        if (this.active && id === this.touchId) {
            if (phase === 'moved') {
                const dx = pos.x - this.center.x;
                const dy = pos.y - this.center.y;
                const dist = Math.hypot(dx, dy);
                const clamped = Math.min(dist, this.radius);
                const angle = Math.atan2(dy, dx);
                this.value = {
                    x: (clamped / this.radius) * Math.cos(angle),
                    y: (clamped / this.radius) * Math.sin(angle)
                };
            } else if (phase === 'ended' || phase === 'cancelled') {
                this.value = { x: 0, y: 0 };
                this.active = false;
            }
        }
    }

    hitTest(pos) {
        const dx = pos.x - this.center.x;
        const dy = pos.y - this.center.y;
        return Math.hypot(dx, dy) < this.radius * 1.5;
    }

    getInput() { return this.value; }
}

