// Unity Addressables loading pattern
using UnityEngine.AddressableAssets;
using UnityEngine.ResourceManagement.AsyncOperations;

public class AssetStreamer : MonoBehaviour {
    private Dictionary<string, GameObject> _cache = new();

    public async void LoadLevel(string levelKey) {
        if (_cache.ContainsKey(levelKey)) {
            Instantiate(_cache[levelKey]);
            return;
        }

        var handle = Addressables
            .LoadAssetAsync<GameObject>(levelKey);
        await handle.Task;

        if (handle.Status == AsyncOperationStatus.Succeeded) {
            _cache[levelKey] = handle.Result;
            Instantiate(handle.Result);
        }
    }

    public void UnloadLevel(string levelKey) {
        if (_cache.TryGetValue(levelKey, out var asset)) {
            Addressables.ReleaseInstance(asset);
            _cache.Remove(levelKey);
        }
    }
}

