// Unity Mirror networking for mobile
using Mirror;
using UnityEngine;

public class MobilePlayer : NetworkBehaviour {
    [SyncVar] public float health = 100f;
    [SyncVar] public Vector3 serverPosition;

    // Client-side prediction
    private Vector3 pendingInput;
    private float ping;

    void Update() {
        if (!isLocalPlayer) return;

        // Collect input
        float moveX = Input.GetAxis("Horizontal");
        float moveY = Input.GetAxis("Vertical");
        pendingInput = new Vector3(moveX, 0, moveY);

        // Client-side prediction
        transform.position += pendingInput * Time.deltaTime * 5f;
    }

    void FixedUpdate() {
        if (isLocalPlayer) {
            CmdMove(pendingInput);
        }
    }

    [Command]
    void CmdMove(Vector3 input) {
        // Server validates and moves
        Vector3 movement = input * Time.fixedDeltaTime * 5f;
        if (Physics.Raycast(transform.position + movement, 
            Vector3.down, 0.1f)) {
            transform.position += movement;
        }
        serverPosition = transform.position;
    }

    void OnGUI() {
        if (isLocalPlayer) {
            ping = NetworkTime.rtt * 1000;
            GUI.Label(new Rect(10, 10, 200, 20), 
                $"Ping: {ping:F0}ms");

            if (ping > 200) {
                GUI.Label(new Rect(10, 30, 200, 20), 
                    "Poor connection");
            }
        }
    }
}

