// Unity AR Foundation placement
using UnityEngine.XR.ARFoundation;
using UnityEngine.XR.ARSubsystems;
using UnityEngine;

public class ARPlacementManager : MonoBehaviour {
    [SerializeField] GameObject placedPrefab;
    [SerializeField] ARRaycastManager raycastManager;
    [SerializeField] ARPlaneManager planeManager;

    private List<ARRaycastHit> hits = new();
    private GameObject spawnedObject;

    void Update() {
        if (Input.touchCount == 0) return;
        Touch touch = Input.GetTouch(0);
        if (touch.phase != TouchPhase.Began) return;

        // Raycast against AR planes
        if (raycastManager.Raycast(
            touch.position, hits, TrackableType.PlaneWithinPolygon)) {
            Pose hitPose = hits[0].pose;

            if (spawnedObject == null) {
                spawnedObject = Instantiate(placedPrefab, 
                    hitPose.position, hitPose.rotation);
            } else {
                spawnedObject.transform.position = hitPose.position;
                spawnedObject.transform.rotation = hitPose.rotation;
            }
        }
    }

    void OnEnable() {
        planeManager.planesChanged += OnPlanesChanged;
    }

    void OnDisable() {
        planeManager.planesChanged -= OnPlanesChanged;
    }

    void OnPlanesChanged(ARPlanesChangedEventArgs args) {
        foreach (var plane in args.added) {
            // Visualize detected planes
            var visualizer = plane.GetComponent<ARPlaneMeshVisualizer>();
            if (visualizer != null) visualizer.enabled = true;
        }
    }

    public void ResetAR() {
        if (spawnedObject != null) {
            Destroy(spawnedObject);
            spawnedObject = null;
        }
    }
}

