// Battle pass progression manager C#
[System.Serializable]
public class BattlePassTier {
    public int tier;
    public int xpRequired;
    public string freeRewardId;
    public string premiumRewardId;
}

public class BattlePassManager : MonoBehaviour {
    public List<BattlePassTier> tiers;
    private int currentTier = 0;
    private int currentXp = 0;
    private bool hasPremium;

    public void AddXp(int amount) {
        currentXp += amount;
        while (currentTier < tiers.Count && currentXp >= tiers[currentTier].xpRequired) {
            currentXp -= tiers[currentTier].xpRequired;
            GrantReward(currentTier);
            currentTier++;
        }
    }

    void GrantReward(int tierIndex) {
        var t = tiers[tierIndex];
        PlayerInventory.AddItem(hasPremium ? t.premiumRewardId : t.freeRewardId, 1);
    }

    public void UnlockPremiumPass() {
        hasPremium = true;
        for (int i = 0; i < currentTier; i++)
            PlayerInventory.AddItem(tiers[i].premiumRewardId, 1);
    }
}

