// Native plugin lifecycle manager
using System.Collections.Concurrent;

public class NativePluginManager : MonoBehaviour {
    private static NativePluginManager _instance;
    private ConcurrentQueue<System.Action> _mainThreadActions = new();

    void Awake() {
        if (_instance != null) { Destroy(gameObject); return; }
        _instance = this;
        DontDestroyOnLoad(gameObject);
        #if UNITY_ANDROID
            AndroidPluginBridge.Init();
        #elif UNITY_IOS
            IOSPluginBridge.Init(gameObject.name);
        #endif
    }

    void Update() {
        while (_mainThreadActions.TryDequeue(out var action)) {
            try { action(); }
            catch (System.Exception e) { Debug.LogError($"Native callback error: {e}"); }
        }
    }

    public void DispatchToMainThread(System.Action action) {
        _mainThreadActions.Enqueue(action);
    }

    void OnApplicationQuit() { /* clean up native resources */ }
}

