struct ARObjectPlacer: View {
    var body: some View {
        ARViewContainer()
            .ignoresSafeArea()
            .overlay(alignment: .bottom) {
                Button("Place Object") {
                    NotificationCenter.default.post(name: .placeObject, object: nil)
                }
                .padding()
                .background(.ultraThinMaterial)
                .clipShape(Capsule())
            }
    }
}

struct ARViewContainer: UIViewRepresentable {
    func makeUIView(context: Context) -> ARView {
        let arView = ARView(frame: .zero)

        let config = ARWorldTrackingConfiguration()
        config.planeDetection = [.horizontal, .vertical]
        config.environmentTexturing = .automatic
        arView.session.run(config)

        // Add tap gesture for placement
        let tap = UITapGestureRecognizer(target: context.coordinator, action: #selector(Coordinator.handleTap(_:)))
        arView.addGestureRecognizer(tap)

        return arView
    }

    func makeCoordinator() -> Coordinator {
        Coordinator()
    }

    class Coordinator: NSObject {
        @objc func handleTap(_ sender: UITapGestureRecognizer) {
            guard let arView = sender.view as? ARView else { return }
            let location = sender.location(in: arView)

            // Raycast against detected planes
            let results = arView.raycast(from: location, allowing: .estimatedPlane, alignment: .horizontal)
            guard let result = results.first else { return }

            // Place 3D model
            let modelEntity = try! ModelEntity.loadModel(named: "furniture.usdz")
            modelEntity.generateCollisionShapes(recursive: true)

            let anchor = AnchorEntity(world: result.worldTransform)
            anchor.addChild(modelEntity)
            arView.scene.addAnchor(anchor)
        }
    }
}

