// Android Performance measurement (Kotlin)
class PerformanceTracker {
    private val frameMetrics = mutableListOf<Long>()

    fun startMonitoring(activity: AppCompatActivity) {
        activity.window.addOnFrameMetricsAvailableListener({ _, metrics, _ } ->
            val frameDuration = metrics.getMetric(FrameMetrics.TOTAL_DURATION)
            frameMetrics.add(frameDuration)

            if (frameDuration > 16_666_666) { // > 16ms = jank (60fps)
                Log.w("Perf", "Frame dropped: ${frameDuration / 1_000_000}ms")
            }
        }, Handler(Looper.getMainLooper()))
    }

    fun reportStats() {
        val total = frameMetrics.size
        val jank = frameMetrics.count { it > 16_666_666 }
        val avgFps = if (total > 0) (total * 60) / (total + jank) else 60

        Firebase.crashlytics.setCustomKey("avg_fps", avgFps)
        Firebase.performance.newTrace("frame_metrics")?.apply {
            putMetric("jank_frames", jank.toLong())
            putMetric("total_frames", total.toLong())
            start()
            stop()
        }
    }
}

// iOS performance with MetricKit
import MetricKit

class PerformanceReporter: MXMetricManagerSubscriber {
    func didReceive(_ payloads: [MXMetricPayload]) {
        for payload in payloads {
            let cpuMetrics = payload.cpuMetrics
            let gpuMetrics = payload.gpuMetrics
            let memoryMetrics = payload.memoryMetrics
            let animationMetrics = payload.animationMetrics

            Logger.performance.info("""
                CPU: \(cpuMetrics?.cumulativeCPUTime ?? 0)
                Memory: \(memoryMetrics?.peakMemoryUsage ?? 0) bytes
                Scroll Hitch: \(animationMetrics?.scrollHitchTimeRatio ?? 0 * 100)%
            """)
        }
    }
}
